CREATE DATABASE IF NOT EXISTS cafeteria CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE cafeteria;
CREATE TABLE IF NOT EXISTS site_settings (id INT PRIMARY KEY AUTO_INCREMENT,site_name VARCHAR(120) NOT NULL,tagline VARCHAR(255),hero_title VARCHAR(200),hero_subtitle TEXT,hero_video_url VARCHAR(1000),hero_poster_url VARCHAR(1000),logo_url VARCHAR(1000),primary_color VARCHAR(20) DEFAULT '#b87849',currency VARCHAR(12) DEFAULT 'Bs');
CREATE TABLE IF NOT EXISTS about (id INT PRIMARY KEY AUTO_INCREMENT,title VARCHAR(200),history TEXT,mission TEXT,address VARCHAR(255),city VARCHAR(120),phone VARCHAR(50),email VARCHAR(180),hours VARCHAR(255),map_url VARCHAR(1000));
CREATE TABLE IF NOT EXISTS services (id INT PRIMARY KEY AUTO_INCREMENT,title VARCHAR(150) NOT NULL,description TEXT,icon VARCHAR(80) DEFAULT '☕',sort_order INT DEFAULT 0,active BOOLEAN DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS categories (id INT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(120) NOT NULL,description TEXT,sort_order INT DEFAULT 0,active BOOLEAN DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS products (id INT PRIMARY KEY AUTO_INCREMENT,category_id INT NOT NULL,name VARCHAR(150) NOT NULL,description TEXT,price DECIMAL(10,2) NOT NULL,image_url VARCHAR(1000),featured BOOLEAN DEFAULT FALSE,available BOOLEAN DEFAULT TRUE,sort_order INT DEFAULT 0,FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE RESTRICT);
CREATE TABLE IF NOT EXISTS gallery (id INT PRIMARY KEY AUTO_INCREMENT,image_url VARCHAR(1000) NOT NULL,alt_text VARCHAR(255),sort_order INT DEFAULT 0,active BOOLEAN DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS social_links (id INT PRIMARY KEY AUTO_INCREMENT,platform VARCHAR(80) NOT NULL,url VARCHAR(1000) NOT NULL,sort_order INT DEFAULT 0);
CREATE TABLE IF NOT EXISTS contact_messages (id BIGINT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(120) NOT NULL,email VARCHAR(180) NOT NULL,phone VARCHAR(40),message TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
